     1→// packages/core/src/account/ops/store.ts
     2→
     3→import { chmod } from "node:fs/promises";
     4→import { readYaml, writeYaml } from "../../config/yaml";
     5→import { getAccountsPath } from "../../config/paths";
     6→import type { AccountRecord } from "./types";
     7→
     8→interface AccountsFile {
     9→  accounts: AccountRecord[];
    10→}
    11→
    12→export function getAccountsFilePath(): string {
    13→  return getAccountsPath();
    14→}
    15→
    16→export async function readAccounts(): Promise<AccountRecord[]> {
    17→  const data = await readYaml<AccountsFile>(getAccountsFilePath());
    18→  return data?.accounts ?? [];
    19→}
    20→
    21→export async function writeAccounts(accounts: AccountRecord[]): Promise<void> {
    22→  const filePath = getAccountsFilePath();
    23→  // writeYaml creates parent dirs if needed
    24→  await writeYaml(filePath, { accounts });
    25→  // Set file permissions to 0600 (owner read/write only)
    26→  await chmod(filePath, 0o600);
    27→}
    28→
    29→export function maskCredential(value: string): string {
    30→  if (value.length <= 4) return "****";
    31→  return "****" + value.slice(-4);
    32→}
