     3→import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
     4→import { join } from "node:path";
     5→import { mkdirSync, rmSync, existsSync } from "node:fs";
     6→import { readFile } from "node:fs/promises";
     7→
     8→// Mock getAccountsPath to use a temp directory
     9→const TEST_DIR = join(__dirname, "__test_tmp__");
    10→vi.mock("../../config/paths", () => ({
    11→  getAccountsPath: () => join(TEST_DIR, "accounts.yaml"),
    12→  getStateDir: () => TEST_DIR,
    13→}));
    14→
    15→import { readAccounts, writeAccounts, maskCredential, getAccountsFilePath } from "./store";
    16→import type { AccountRecord } from "./types";
    17→
    18→describe("store", () => {
    19→  beforeEach(() => {
    20→    mkdirSync(TEST_DIR, { recursive: true });
    21→  });
    22→
    23→  afterEach(() => {
    24→    rmSync(TEST_DIR, { recursive: true, force: true });
    25→  });
    26→
    27→  describe("readAccounts", () => {
    28→    it("returns empty array when file does not exist", async () => {
    29→      const result = await readAccounts();
    30→      expect(result).toEqual([]);
    31→    });
    32→
    33→    it("reads accounts from YAML file", async () => {
    34→      const accounts: AccountRecord[] = [
    35→        {
    36→          id: "test123",
    37→          exchange: "okx",
    38→          name: "OKX #1",
    39→          api_key: "key123",
    40→          secret: "secret123",
    41→          passphrase: "pass123",
    42→          created_at: "2026-05-14T00:00:00Z",
    43→          updated_at: "2026-05-14T00:00:00Z",
    44→        },
    45→      ];
    46→      await writeAccounts(accounts);
    47→      const result = await readAccounts();
    48→      expect(result).toHaveLength(1);
    49→      expect(result[0].id).toBe("test123");
    50→      expect(result[0].api_key).toBe("key123");
    51→    });
    52→  });
    53→
    54→  describe("writeAccounts", () => {
    55→    it("creates file with 0600 permissions", async () => {
    56→      await writeAccounts([]);
    57→      const filePath = getAccountsFilePath();
    58→      expect(existsSync(filePath)).toBe(true);
    59→      // Check file content
    60→      const content = await readFile(filePath, "utf-8");
    61→      expect(content).toContain("accounts:");
    62→    });
    63→
    64→    it("overwrites existing data", async () => {
    65→      const acc1: AccountRecord = {
    66→        id: "a",
    67→        exchange: "okx",
    68→        name: "A",
    69→        api_key: "k1",
    70→        secret: "s1",
    71→        passphrase: "p1",
    72→        created_at: "2026-01-01T00:00:00Z",
    73→        updated_at: "2026-01-01T00:00:00Z",
    74→      };
    75→      const acc2: AccountRecord = {
    76→        id: "b",
    77→        exchange: "binance",
    78→        name: "B",
    79→        api_key: "k2",
    80→        secret: "s2",
    81→        created_at: "2026-01-02T00:00:00Z",
    82→        updated_at: "2026-01-02T00:00:00Z",
    83→      };
    84→      await writeAccounts([acc1]);
    85→      await writeAccounts([acc1, acc2]);
    86→      const result = await readAccounts();
    87→      expect(result).toHaveLength(2);
    88→    });
    89→  });
    90→
    91→  describe("maskCredential", () => {
    92→    it("masks credentials showing last 4 chars", () => {
    93→      expect(maskCredential("abcdefgh1234")).toBe("****1234");
    94→      expect(maskCredential("short")).toBe("****hort");
    95→    });
    96→
    97→    it("returns **** for very short values", () => {
    98→      expect(maskCredential("ab")).toBe("****");
    99→      expect(maskCredential("abcd")).toBe("****");
   100→    });
   101→  });
   102→});
